import { HTMLChakraProps, Link } from '@chakra-ui/react'
import { Link as ReactRouterLink } from 'react-router-dom'

interface NavLinkProps extends HTMLChakraProps<'span'> {
  children: React.ReactNode
  link: string
  type?: 'reactRouterLink' | '_blank' // 空为a标签
  isActive?: boolean
  target?: string
  fontSize?: string | number
}
export default function NavLink(props: NavLinkProps) {
  const { children, link, type = 'reactRouterLink', isActive, fontSize, ...rest } = props

  const style = {
    fontFamily: 'Inter, sans-serif',
    color: isActive ? 'text_caption' : 'text_paragraph',
    fontSize: fontSize || '15px',
    cursor: 'pointer',
    height: '24px',
    lineHeight: '24px',
    _hover: {
      color: 'text_caption'
    }
  }

  return type === 'reactRouterLink' ? (
    <Link as={ReactRouterLink} to={link} {...style} {...rest}>
      {children}
    </Link>
  ) : (
    <Link href={link} target="_blank" {...style} {...rest}>
      {children}
    </Link>
  )
}
